import React, { useState, useEffect, useCallback, useRef } from 'react'
import { Button, Card, Space, Typography, Input, InputNumber, Modal, Select, Tag, Spin, Divider, Empty, Tooltip, message, Tabs, Progress, Dropdown, Drawer, Checkbox, Switch, Steps } from 'antd'
import type { MenuProps } from 'antd'
import { PlusOutlined, FileTextOutlined, RobotOutlined, ExportOutlined, DeleteOutlined, EditOutlined, FormatPainterOutlined, ExpandOutlined, CompressOutlined, PieChartOutlined, EyeOutlined, UploadOutlined, CheckCircleOutlined, WarningOutlined, CloseCircleOutlined, RightOutlined, DownOutlined, UnorderedListOutlined, LeftOutlined, CopyOutlined, BookOutlined, ArrowUpOutlined, ArrowDownOutlined } from '@ant-design/icons'
import { SaveOutlined } from '@ant-design/icons'
import { ParseSummaryCards, type BidSummaryShape, type SrcRef } from '../components/office/ParseSummaryCards'
import { SourcePreviewDrawer } from '../components/office/SourcePreviewDrawer'
import * as App from '../../wailsjs/go/app/App'
import { EventsOn } from '../../wailsjs/runtime/runtime'
import mermaid from 'mermaid'
import FeatureModelBar from '../components/FeatureModelBar'
import './office-page.css'
mermaid.initialize({ startOnLoad: false, theme: 'default', securityLevel: 'loose' })
const { Title, Text, Paragraph } = Typography; const { TextArea } = Input

interface PS { id: string; proposalId: string; parentId: string; index: number; level: number; title: string; content: string; status: string; wordTarget?: number; words?: number; children?: PS[] }
interface FD { name: string; path: string; markdown: string; size: number; error?: string; ocrStatus?: string }
interface BS { techScoring?: { name: string; maxScore: string; requirement: string }[]; keyRequirements?: string[]; duration?: string; redLines?: string[]; overview?: string; extra?: Record<string, string>; rawMarkdown?: string; rawFiles?: FD[]; totalWords?: number; qualification?: { name?: string }[] }
interface P { id: string; projectId?: string; title: string; category: string; template: string; requirements: string; status: string; version?: number; stage?: string; checkSummary?: { failed?: number; warnings?: number; total?: number }; reviewChecklist?: { id: string; label: string; done: boolean }[]; sections: PS[]; bidSummary?: BS; createdAt: string; updatedAt: string }
interface PR { id: string; name: string; category: string; client: string; status: string }
interface T { id: string; name: string; description: string; sections: string[] }
const ct = [{ v: 'flowchart', l: '流程图' },{ v: 'sequence', l: '时序图' },{ v: 'gantt', l: '横道图（甘特图）' },{ v: 'process-flow', l: '工艺流程图' },{ v: 'org-chart', l: '组织架构图' },{ v: 'pie', l: '饼图' },{ v: 'graph', l: '架构图' },{ v: 'mindmap', l: '思维导图' }]
const cats = ['全部', '环保工程', '市政工程', '水利工程', '建筑工程', '其他']
const cc2: Record<string, string> = { '环保工程': 'green', '市政工程': 'blue', '水利工程': 'cyan', '建筑工程': 'orange', '其他': 'default' }
const gb = 'var(--whisper-glass-bg)'; const cst: React.CSSProperties = { background: gb, backdropFilter: 'blur(20px)', height: '100%', overflow: 'auto' }

function flatS(ss: PS[]): PS[] { const r: PS[] = []; for (const s of ss) { r.push(s); if (s.children?.length) r.push(...flatS(s.children)) } return r }
function updTree(ss: PS[], id: string, fn: (s: PS) => PS): PS[] {
  return ss.map(s => { if (s.id === id) return fn(s); if (s.children?.length) return { ...s, children: updTree(s.children, id, fn) }; return s })
}
function ON({ sec, sid, onS, d, onAdd, onRename, onDel, onMove }: { sec: PS; sid: string | null; onS: (id: string) => void; d: number; onAdd?: (id: string) => void; onRename?: (id: string) => void; onDel?: (id: string) => void; onMove?: (id: string, delta: number) => void }) {
  const [o, setO] = useState(d < 2); const h = sec.children && sec.children.length > 0
  const acts = onAdd || onRename || onDel || onMove
  return <div><div onClick={() => { if (h) setO(!o); onS(sec.id) }} style={{ padding: '3px 4px', paddingLeft: 8 + d * 16, borderRadius: 4, cursor: 'pointer', background: sid === sec.id ? 'var(--md-sys-color-primary-container)' : 'transparent', display: 'flex', alignItems: 'center', gap: 4, fontSize: 12 }}>{h ? (o ? <DownOutlined style={{ fontSize: 10 }} /> : <RightOutlined style={{ fontSize: 10 }} />) : <span style={{ width: 10 }} />}<Text style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontWeight: sid === sec.id ? 600 : (sec.level === 1 ? 600 : undefined) }}>{sec.title}</Text>{sec.wordTarget ? <Tag style={{ fontSize: 9, marginInlineEnd: 2 }}>目标{sec.wordTarget}</Tag> : null}{sec.status === 'completed' && <span style={{ color: '#52c41a', fontSize: 10 }}>✓</span>}{acts && <span style={{ display: 'inline-flex', alignItems: 'center' }} onClick={e => e.stopPropagation()}>{onMove && <><Tooltip title="上移"><Button type="text" size="small" icon={<ArrowUpOutlined style={{ fontSize: 10 }} />} onClick={() => onMove(sec.id, -1)} style={{ padding: 0, minWidth: 16, height: 16 }} /></Tooltip><Tooltip title="下移"><Button type="text" size="small" icon={<ArrowDownOutlined style={{ fontSize: 10 }} />} onClick={() => onMove(sec.id, 1)} style={{ padding: 0, minWidth: 16, height: 16 }} /></Tooltip></>}{onAdd && <Tooltip title="新增子章节"><Button type="text" size="small" icon={<PlusOutlined style={{ fontSize: 10 }} />} onClick={() => onAdd(sec.id)} style={{ padding: 0, minWidth: 16, height: 16 }} /></Tooltip>}{onRename && <Tooltip title="重命名"><Button type="text" size="small" icon={<EditOutlined style={{ fontSize: 10 }} />} onClick={() => onRename(sec.id)} style={{ padding: 0, minWidth: 16, height: 16 }} /></Tooltip>}{onDel && <Tooltip title="删除"><Button type="text" size="small" danger icon={<DeleteOutlined style={{ fontSize: 10 }} />} onClick={() => onDel(sec.id)} style={{ padding: 0, minWidth: 16, height: 16 }} /></Tooltip>}</span>}</div>{o && h && sec.children!.map(c => <ON key={c.id} sec={c} sid={sid} onS={onS} d={d + 1} onAdd={onAdd} onRename={onRename} onDel={onDel} onMove={onMove} />)}</div>
}

const ShelvesTab: React.FC<{ pp: P[]; prs: PR[]; sid: string | null; onS: (id: string) => void; onN: () => void; onD: (id: string) => void; tt: T[] }> = ({ pp, prs, sid, onS, onN, onD, tt }) => {
  const [f, setF] = useState('全部')
  const tn = (id: string) => tt.find(t => t.id === id)?.name || id
  const fl = f === '全部' ? pp : pp.filter(p => p.category === f)
  const pname = (id?: string) => prs.find(x => x.id === id)?.name || '未分组'
  const groups = prs.map(pr => ({ key: pr.id, name: pr.name, items: fl.filter(p => p.projectId === pr.id) })).filter(g => g.items.length > 0)
  const orphan = fl.filter(p => !prs.some(pr => pr.id === p.projectId))
  const renderItem = (p: P) => (
    <div key={p.id} onClick={() => onS(p.id)} style={{ display: 'flex', alignItems: 'center', padding: '10px 14px', borderRadius: 8, cursor: 'pointer', marginBottom: 6, background: sid === p.id ? 'var(--md-sys-color-primary-container)' : gb, border: sid === p.id ? '1px solid var(--md-sys-color-primary)' : '1px solid transparent', gap: 12 }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <Text strong style={{ fontSize: 14 }}>{p.title}</Text>
        <div style={{ display: 'flex', gap: 4, marginTop: 2, flexWrap: 'wrap' }}>
          {p.category && <Tag color={cc2[p.category] || 'default'} style={{ fontSize: 10 }}>{p.category}</Tag>}
          <Tag style={{ fontSize: 10 }}>{tn(p.template)}</Tag>
          <Tag color={p.status === 'completed' ? 'green' : p.status === 'writing' ? 'blue' : 'default'} style={{ fontSize: 10 }}>{p.status === 'completed' ? '完成' : p.status === 'writing' ? '撰写中' : '草稿'}</Tag>
          {p.bidSummary?.techScoring?.length ? <Tag color="purple" style={{ fontSize: 10 }}>已解析</Tag> : null}
        </div>
      </div>
      <Text type="secondary" style={{ fontSize: 11, whiteSpace: 'nowrap' }}>{p.updatedAt?.slice(0, 10)}</Text>
      <Button type="text" size="small" danger icon={<DeleteOutlined />} onClick={e => { e.stopPropagation(); onD(p.id) }} />
    </div>
  )
  return <div style={{ padding: 16, height: '100%', display: 'flex', flexDirection: 'column' }}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}><Space><Title level={4} style={{ margin: 0 }}>方案列表</Title><Select value={f} onChange={setF} style={{ width: 110 }} options={cats.map(c => ({ value: c, label: c }))} /></Space><Button type="primary" icon={<PlusOutlined />} onClick={onN}>新建方案</Button></div>{fl.length === 0 ? <Empty description="暂无方案" /> : <div style={{ flex: 1, overflow: 'auto' }}>{groups.map(g => (
    <div key={g.key} style={{ marginBottom: 16 }}>
      <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--md-sys-color-primary)', marginBottom: 6 }}>{g.name}（{g.items.length}）</div>
      {g.items.map(p => renderItem(p))}
    </div>
  ))}
    {orphan.length > 0 && (
      <div style={{ marginBottom: 16 }}>
        <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--md-sys-color-outline)', marginBottom: 6 }}>未分组（{orphan.length}）</div>
        {orphan.map(p => renderItem(p))}
      </div>
    )}
  </div>}</div>
}

const ParseTab: React.FC<{ sid: string | null; sp: P | undefined; onR: () => void }> = ({ sid, sp, onR }) => {
  const [bp, setBp] = useState(false); const [cv, setCv] = useState(false); const [pg, setPg] = useState({ cur: 0, total: 0, name: '', status: '' })
  const [editBS, setEditBS] = useState<BidSummaryShape>(sp?.bidSummary || {}); const [src, setSrc] = useState<SrcRef | null>(null); const files = sp?.bidSummary?.rawFiles || []
  const [stage, setStage] = useState(''); const [stageDetail, setStageDetail] = useState(''); const [aiLogs, setAiLogs] = useState<{ t: string; stage: string; detail: string }[]>([]); const [aiOpen, setAiOpen] = useState(false); const [convOpen, setConvOpen] = useState(false); const [convFile, setConvFile] = useState<FD | null>(null); const aiLogRef = useRef<HTMLDivElement>(null)
  const allDone = files.length > 0 && files.every(f => f.markdown); const anyDone = files.some(f => f.markdown); const hasSummary = !!(sp?.bidSummary?.techScoring && sp.bidSummary.techScoring.length > 0)
  useEffect(() => { const u = EventsOn('proposal-convert-progress', (d: any) => { if (d.type === 'error') { setCv(false); return }; setPg({ cur: d.current || 0, total: d.total || 0, name: d.filename || '', status: d.status || '' }); setAiLogs(ls => [...ls, { t: new Date().toLocaleTimeString(), stage: 'convert', detail: (d.filename || '') + ' — ' + (d.status || '') }]); if (d.current === d.total) { setCv(false); onR() } }); return () => { if (typeof u === 'function') u() } }, [onR])
  useEffect(() => { const u = EventsOn('proposal-ai-progress', (d: any) => { setStage(d.stage || ''); setStageDetail(d.detail || ''); setAiLogs(ls => [...ls, { t: new Date().toLocaleTimeString(), stage: d.stage || '', detail: d.detail || '' }]); if (d.stage === 'done') { setBp(false); onR() } else if (d.stage === 'error') { setBp(false); message.error(d.detail || 'AI 分析失败') } }); return () => { if (typeof u === 'function') u() } }, [onR])
  useEffect(() => { if (aiLogRef.current) aiLogRef.current.scrollTop = aiLogRef.current.scrollHeight }, [aiLogs])
  useEffect(() => { setEditBS(sp?.bidSummary || {}) }, [sp?.bidSummary])
  const hpb = () => { if (!sid) return; setBp(true); App.ProposalParseBidFileWithProgress(sid) }
  const hcv = () => { if (!sid) return; setCv(true); App.ProposalConvertFiles(sid) }
  const hf = async (e: React.ChangeEvent<HTMLInputElement>) => { const fl = e.target.files; if (!fl?.length) return; try { for (let i = 0; i < fl.length; i++) { const f = fl[i]; const bytes = new Uint8Array(await f.arrayBuffer()); await App.ProposalSaveUploadedFile(sid!, f.name, Array.from(bytes)) } message.success(`已添加 ${fl.length} 个文件，点击「转换 Markdown」`); onR() } catch (ex: any) { message.error(String(ex)) }; e.target.value = '' }
  const del = async (i: number) => { try { await App.ProposalRemoveRawFile(sid!, i); onR() } catch (ex: any) { message.error(String(ex)) } }
  const save = async () => { if (!sid) return; try { await App.ProposalUpdate({ ...sp, bidSummary: editBS } as any); onR(); message.success('已保存') } catch (e: any) { message.error(String(e)) } }
  return <div style={{ padding: 16, height: '100%', overflow: 'auto' }}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><Title level={4} style={{ margin: 0 }}>招标解析</Title><Button size="small" icon={<RobotOutlined />} onClick={() => setAiOpen(true)}>AI 工作台</Button></div>{!sid ? <Empty description="请先选择方案" /> : <><Card size="small" style={{ ...cst, marginBottom: 12 }}><Space direction="vertical" style={{ width: '100%' }} size={8}><Text strong>第1步：上传文件 → 转换 Markdown</Text><Space><input type="file" id="bfi3" accept=".pdf,.txt,.doc,.docx" multiple style={{ display: 'none' }} onChange={hf} /><Button icon={<UploadOutlined />} onClick={() => document.getElementById('bfi3')?.click()}>上传文件</Button><Button type="primary" icon={<RobotOutlined />} loading={cv} onClick={hcv} disabled={files.length === 0 || allDone}>{cv ? '转换中...' : allDone ? '已转换 ✓' : '转换 Markdown'}</Button>{files.length > 0 && <Tag color="blue">{files.length} 个文件 | {files.filter(f => f.markdown).length} 已转换</Tag>}</Space>{cv && <div style={{ background: 'rgba(0,0,0,0.03)', borderRadius: 8, padding: '8px 12px' }}><Progress percent={pg.total > 0 ? Math.round(pg.cur / pg.total * 100) : 0} size="small" /><Text type="secondary" style={{ fontSize: 12 }}>{pg.name} — {pg.status}</Text></div>}{files.length > 0 && <div style={{ background: gb, borderRadius: 8, padding: 8 }}>{files.map((f, i) => <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 8px', fontSize: 12 }}><Space><FileTextOutlined /><Text>{f.name}</Text><Tag color={f.markdown ? (f.ocrStatus ? 'purple' : 'green') : f.error ? 'red' : 'orange'} style={{ fontSize: 10 }}>{f.markdown ? (f.ocrStatus ? 'OCR 转换' : '已转换') : f.error ? '转换失败' : '待转换'}</Tag>{f.error && <Tooltip title={f.error}><WarningOutlined style={{ color: '#ff4d4f' }} /></Tooltip>}<Button type="link" size="small" style={{ padding: 0 }} onClick={() => { setConvFile(f); setConvOpen(true) }}>查看</Button></Space><Button type="text" size="small" danger icon={<DeleteOutlined />} onClick={() => del(i)} /></div>)}</div>}<Divider style={{ margin: '4px 0' }} /><Text strong>第2步：AI 分析整理 → 摘要文档（可编辑）</Text><Button type="primary" icon={<RobotOutlined />} loading={bp} onClick={hpb} disabled={!anyDone || hasSummary}>{hasSummary ? '已分析 ✓' : 'AI 分析'}</Button>{bp && <span style={{ marginLeft: 8 }}><Spin size="small" /> {stage} {stageDetail}</span>}</Space></Card>{hasSummary && <Card size="small" style={cst} title="招标关键内容摘要（可编辑）" extra={<Space><Button size="small" type="primary" icon={<SaveOutlined />} onClick={save}>保存</Button></Space>}><ParseSummaryCards bs={editBS} onChange={setEditBS} onJump={s => setSrc(s)} /></Card>}{hasSummary && <SourcePreviewDrawer open={!!src} files={files} source={src} onClose={() => setSrc(null)} />}<Drawer title={"转换结果：" + (convFile?.name || '')} width={560} open={convOpen} onClose={() => setConvOpen(false)}><div style={{ marginBottom: 8 }}>{convFile?.markdown ? <Tag color={convFile.ocrStatus ? 'purple' : 'green'}>{convFile.ocrStatus ? 'OCR 识别' : '文本提取'}</Tag> : convFile?.error ? <Tag color="red">转换失败</Tag> : <Tag>未转换</Tag>}</div><div style={{ whiteSpace: 'pre-wrap', fontSize: 13, lineHeight: 1.8 }}>{convFile?.markdown || convFile?.error || '（暂无转换内容）'}</div></Drawer><Drawer title="AI 工作台" width={460} open={aiOpen} onClose={() => setAiOpen(false)}><div ref={aiLogRef} style={{ maxHeight: 'calc(100vh - 120px)', overflow: 'auto' }}>{aiLogs.length === 0 ? <Empty description="暂无 AI 日志" /> : aiLogs.map((l, i) => (<div key={i} style={{ padding: '6px 0', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}><Text type="secondary" style={{ fontSize: 11 }}>{l.t} · {l.stage}</Text><div style={{ fontSize: 12 }}>{l.detail}</div></div>))}</div></Drawer></>}</div>
}

const OutlineTab: React.FC<{ sid: string | null; sp: P | undefined; ssid: string | null; onSS: (id: string) => void; onR: () => void; onAdd: (id: string) => void; onRename: (id: string) => void; onDel: (id: string) => void }> = ({ sid, sp, ssid, onSS, onR, onAdd, onRename, onDel }) => {
  const [ai, setAi] = useState(false); const [strategy, setStrategy] = useState('reference'); const [totalWords, setTotalWords] = useState(sp?.bidSummary?.totalWords || 100000); const [oiOpen, setOiOpen] = useState(false); const [oiMd, setOiMd] = useState('')
  const hgo = async () => { if (!sid) return; setAi(true); try { await App.ProposalGenerateOutline(sid, sp?.requirements || '', strategy, totalWords); onR() } catch (e: any) { message.error(String(e)) }; setAi(false) }
  const hm = async (id: string, delta: number) => { if (!sid) return; try { await App.ProposalMoveSection(sid, id, delta); onR() } catch (e: any) { message.error(String(e)) } }
  const doImport = async () => { if (!sid || !oiMd.trim()) return; try { await App.ProposalImportOutline(sid, oiMd); setOiOpen(false); setOiMd(''); onR(); message.success('已导入') } catch (e: any) { message.error(String(e)) } }
  return <div style={{ padding: 16, height: '100%', display: 'flex', flexDirection: 'column' }}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}><Title level={4} style={{ margin: 0 }}>大纲生成</Title><Space><Select value={strategy} onChange={setStrategy} style={{ width: 170 }} options={[{ value: 'scoring', label: '严格按评标办法' }, { value: 'format', label: '严格按格式要求' }, { value: 'reference', label: '参考评标办法及格式' }]} /><InputNumber value={totalWords} onChange={v => setTotalWords(v || 0)} min={0} step={10000} style={{ width: 150 }} /><Button icon={<UploadOutlined />} onClick={() => setOiOpen(true)} disabled={!sid}>导入目录</Button><Button type="primary" icon={<RobotOutlined />} loading={ai} onClick={hgo} disabled={!sid}>AI 生成大纲</Button><Button icon={<PlusOutlined />} onClick={() => onAdd('')} disabled={!sid}>新增章节</Button></Space></div>{!sid ? <Empty description="请先选择方案" /> : !sp?.sections?.length ? <Empty description="点击生成或手动新增" /> : <Card size="small" style={{ flex: 1, ...cst }}><div style={{ overflow: 'auto' }}>{sp.sections.map(sec => <ON key={sec.id} sec={sec} sid={ssid} onS={onSS} d={0} onAdd={onAdd} onRename={onRename} onDel={onDel} onMove={hm} />)}</div></Card>}<Modal title="导入 Markdown 目录" open={oiOpen} onOk={doImport} onCancel={() => { setOiOpen(false); setOiMd('') }} okText="导入并替换" width={560}><Text type="secondary">支持 #/##/### 标题，导入后将替换现有大纲</Text><TextArea value={oiMd} onChange={e => setOiMd(e.target.value)} rows={12} style={{ marginTop: 8, fontFamily: 'monospace' }} /></Modal></div>
}

const WriteTab: React.FC<{ sid: string | null; sp: P | undefined; ssid: string | null; onSS: (id: string) => void; onR: () => void; onAdd: (id: string) => void; onRename: (id: string) => void; onDel: (id: string) => void }> = ({ sid, sp, ssid, onSS, onR, onAdd, onRename, onDel }) => {
  const all = sp ? flatS(sp.sections) : []; const ss = all.find(s => s.id === ssid)
  const [ec, setEc] = useState(''); const [pm, setPm] = useState(false); const pr = useRef<HTMLDivElement>(null)
  const [st, setSt] = useState(false); const [stt, setStt] = useState(0); const [fc, setFc] = useState(false); const ctRef = useRef<ReturnType<typeof setTimeout> | null>(null); const [ai, setAi] = useState(false)
  const [batch, setBatch] = useState<{ cur: number; total: number; status: string; title: string } | null>(null)
  useEffect(() => { setEc(ss?.content || '') }, [ssid])
  useEffect(() => { const u = EventsOn('proposal-stream', (d: any) => { if (d.type === 'chunk') { setEc(p => p + d.content); setStt(d.total || 0) } else if (d.type === 'done') { setSt(false); setEc(d.content || ''); onR() } else if (d.type === 'error') { setSt(false); message.error(d.error || '生成失败') } }); return () => { if (typeof u === 'function') u() } }, [onR])
  useEffect(() => { const u = EventsOn('proposal-batch-progress', (d: any) => { setBatch({ cur: d.current || 0, total: d.total || 0, status: d.status || '', title: all.find(x => x.id === d.sectionId)?.title || '' }); if (d.status === 'done' && d.current === d.total) onR() }); return () => { if (typeof u === 'function') u() } }, [all, onR])
  useEffect(() => { const h = (e: KeyboardEvent) => { if (e.key === 'F11') { e.preventDefault(); setFc(f => !f) } }; window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h) }, [])
  const occ = useCallback((v: string) => { setEc(v); if (ctRef.current) clearTimeout(ctRef.current); ctRef.current = setTimeout(async () => { if (!sid || !ssid || !sp) return; try { await App.ProposalUpdate({ ...sp, sections: updTree(sp.sections, ssid, s => ({ ...s, content: v, status: 'completed' })) } as any) } catch (e) { } }, 2000) }, [sid, ssid, sp])
  const go = (d: number) => { const i = all.findIndex(s => s.id === ssid); const n = all[i + d]; if (n) { onSS(n.id); setEc(n.content || '') } }
  const hgs = () => { if (!sid || !ssid) return; setSt(true); setEc(''); App.ProposalGenerateSectionStream(sid, ssid, '') }
  const hp = async (op: string) => { if (!sid || !ssid) return; setAi(true); try { const r = await App.ProposalPolish(sid, ssid, ec, op) as any; onR(); const s = flatS(r.sections || []).find((x: any) => x.id === ssid); if (s) setEc(s.content || '') } catch (e: any) { message.error(String(e)) }; setAi(false) }
  useEffect(() => { if (!pm || !pr.current) return; pr.current.innerHTML = rm(ec); let id = 0; pr.current.querySelectorAll('pre code.language-mermaid').forEach(async b => { try { const { svg } = await mermaid.render('m' + (id++), b.textContent || ''); const p = b.parentElement; if (p) p.outerHTML = svg } catch (e) { } }) }, [pm, ec])
  const ctx: MenuProps['items'] = [{ key: 'polish', label: '润色', icon: <FormatPainterOutlined />, onClick: () => hp('polish') },{ key: 'expand', label: '扩写', icon: <ExpandOutlined />, onClick: () => hp('expand') },{ key: 'shorten', label: '精简', icon: <CompressOutlined />, onClick: () => hp('shorten') }]
  return <div style={{ padding: 16, height: '100%', display: 'flex', flexDirection: 'column', minWidth: 0 }}><Title level={4} style={{ margin: '0 0 12px' }}>文本编制</Title>{!sid ? <Empty description="请先选择方案" /> : <div style={{ display: 'flex', gap: 12, flex: 1, minHeight: 0 }}>{!fc && <Card size="small" style={{ width: 210, flexShrink: 0, ...cst }} title="章节"><div style={{ overflow: 'auto' }}>{sp?.sections?.map(sec => <ON key={sec.id} sec={sec} sid={ssid} onS={onSS} d={0} onAdd={onAdd} onRename={onRename} onDel={onDel} />)}</div></Card>}<Card size="small" style={{ flex: 1, display: 'flex', flexDirection: 'column', ...cst }} title={<Space><EditOutlined /><Text strong>{ss?.title || '选择章节'}</Text>{st && <Tag color="processing">生成中</Tag>}</Space>} extra={<Space size={4} wrap><Tooltip title="上一节"><Button size="small" icon={<LeftOutlined />} onClick={() => go(-1)} disabled={!ssid || all.indexOf(ss!) <= 0} /></Tooltip><Tooltip title="下一节"><Button size="small" icon={<RightOutlined />} onClick={() => go(1)} disabled={!ssid || all.indexOf(ss!) >= all.length - 1} /></Tooltip><Divider type="vertical" /><Tooltip title="AI 流式撰写"><Button type="primary" size="small" icon={<RobotOutlined />} loading={st} onClick={hgs} disabled={!ssid}>撰写</Button></Tooltip><Tooltip title="按章节批量生成全部"><Button type="primary" size="small" icon={<RobotOutlined />} onClick={() => App.ProposalBatchGenerate(sid!)} disabled={!sid}>批量生成</Button></Tooltip><Button size="small" onClick={() => App.ProposalBatchCancel(sid!)} disabled={!sid}>停止</Button><Dropdown menu={{ items: ctx }} trigger={['click']}><Button size="small" icon={<FormatPainterOutlined />} disabled={!ssid || !ec}>AI加工</Button></Dropdown><Tooltip title={pm ? '编辑' : '预览'}><Button size="small" icon={<EyeOutlined />} type={pm ? 'primary' : 'default'} onClick={() => setPm(!pm)}>{pm ? '编辑' : '预览'}</Button></Tooltip><Tooltip title="F11专注"><Button size="small" onClick={() => setFc(!fc)}>{fc ? '退出专注' : '专注'}</Button></Tooltip></Space>}>{!ssid ? <Empty description="选择章节" /> : pm ? <div ref={pr} className="md-content" style={{ flex: 1, overflow: 'auto', padding: '0 4px', fontSize: 14, lineHeight: 1.8 }} /> : <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>{batch && batch.total > 0 && <div style={{ marginBottom: 6 }}><Progress percent={Math.round(batch.cur / batch.total * 100)} size="small" /><Text type="secondary" style={{ fontSize: 12 }}>{batch.status === 'done' ? '已生成' : batch.status === 'skipped' ? '跳过' : batch.status === 'error' ? '失败' : '生成中'}：{batch.title}（{batch.cur}/{batch.total}）</Text></div>}{st && <Progress percent={Math.min(100, Math.round(stt / 5))} size="small" style={{ marginBottom: 4 }} />}<TextArea value={ec} onChange={e => occ(e.target.value)} placeholder="编辑内容... 点击「撰写」AI 流式生成" style={{ flex: 1, fontFamily: 'system-ui, sans-serif', fontSize: 14, lineHeight: 1.8, border: 'none', resize: 'none', background: 'transparent' }} /></div>}</Card></div>}</div>
}

const ChartTab: React.FC<{ sid: string | null; sp: P | undefined; ssid: string | null; onSS: (id: string) => void; onR: () => void; onAdd: (id: string) => void; onRename: (id: string) => void; onDel: (id: string) => void }> = ({ sid, sp, ssid, onSS, onR, onAdd, onRename, onDel }) => {
  const [ctp, setCtp] = useState('flowchart'); const [cc3, setCc3] = useState(''); const [cg, setCg] = useState(false)
  const hgc = async () => { if (!sid || !ssid) return; setCg(true); try { const r = await App.ProposalGenerateChart(sid, ssid, ctp) as any; setCc3(r.mermaidCode || '') } catch (e: any) { message.error(String(e)) }; setCg(false) }
  const hic = async () => { if (!cc3 || !ssid || !sp) return; try { await App.ProposalUpdate({ ...sp, sections: updTree(sp.sections, ssid, s => ({ ...s, content: (s.content || '') + '\n\n```mermaid\n' + cc3 + '\n```\n', status: 'completed' })) } as any); onR(); setCc3(''); message.success('已插入') } catch (e: any) { message.error(String(e)) } }
  return <div style={{ padding: 16, height: '100%', display: 'flex', flexDirection: 'column' }}><Title level={4} style={{ margin: '0 0 12px' }}>图表制作</Title>{!sid ? <Empty description="请先选择方案" /> : <div style={{ display: 'flex', gap: 12, flex: 1, minHeight: 0 }}><Card size="small" style={{ width: 210, flexShrink: 0, ...cst }} title="章节">{sp?.sections?.map(sec => <ON key={sec.id} sec={sec} sid={ssid} onS={onSS} d={0} onAdd={onAdd} onRename={onRename} onDel={onDel} />)}</Card><Card size="small" style={{ flex: 1, ...cst }} title="图表" extra={<Space><Select value={ctp} onChange={setCtp} style={{ width: 120 }} options={ct.map(t => ({ value: t.v, label: t.l }))} /><Button type="primary" icon={<RobotOutlined />} loading={cg} onClick={hgc} disabled={!ssid}>生成</Button></Space>}>{cc3 ? <div><TextArea value={cc3} onChange={e => setCc3(e.target.value)} rows={8} style={{ fontFamily: 'monospace', fontSize: 12, marginBottom: 12 }} /><Space><Button type="primary" onClick={hic}>插入</Button><Button onClick={() => { navigator.clipboard.writeText('```mermaid\n' + cc3 + '\n```'); message.success('已复制') }} icon={<CopyOutlined />}>复制</Button></Space></div> : <Empty description="选择章节和图表类型" />}</Card></div>}</div>
}

const ExportTab: React.FC<{ sid: string | null; sp: P | undefined; onR: () => void; onGoto: (id: string) => void }> = ({ sid, sp, onR, onGoto }) => {
  const [covr, setCovr] = useState<any[]>([]); const [covg, setCovg] = useState(false); const [compr, setCompr] = useState<any[]>([]); const [compg, setCompg] = useState(false)
  const [archiving, setArchiving] = useState(false); const [chk, setChk] = useState<any[]>([]); const [chkg, setChkg] = useState(false)
  const [expOpen, setExpOpen] = useState(false); const [includeCover, setIncludeCover] = useState(true); const [includeTOC, setIncludeTOC] = useState(true); const [darkRuleID, setDarkRuleID] = useState(''); const [darkRules, setDarkRules] = useState<any[]>([]); const [darkOpen, setDarkOpen] = useState(false); const [darkEdit, setDarkEdit] = useState<any | null>(null); const [secSel, setSecSel] = useState('')
  const hed = async () => { if (!sid) return; try { message.success('Word 已导出: ' + await App.ProposalExportDocx(sid)) } catch (e: any) { message.error(String(e)) } }
  const he = async () => { if (!sid) return; try { message.success('已导出: ' + await App.ProposalExport(sid)) } catch (e: any) { message.error(String(e)) } }
  const hcov = async () => { if (!sid) return; setCovg(true); try { const r = await App.ProposalCheckCoverage(sid) as any; setCovr(r.coverage || []) } catch (e: any) { message.error(String(e)) }; setCovg(false) }
  const hcomp = async () => { if (!sid) return; setCompg(true); try { const r = await App.ProposalCheckCompliance(sid) as any; setCompr(r.items || []) } catch (e: any) { message.error(String(e)) }; setCompg(false) }
  const harchive = async () => { if (!sid) return; setArchiving(true); try { const name = await App.ProposalArchive(sid); message.success('已归档：' + name) } catch (e: any) { message.error(String(e)) }; setArchiving(false) }
  const hchk = async () => { if (!sid) return; setChkg(true); try { const r = await App.ProposalCheckAll(sid) as any; setChk(r.items || []); onR() } catch (e: any) { message.error(String(e)) }; setChkg(false) }
  const loadDarkRules = async () => { try { setDarkRules((await App.ProposalDarkRulesList() as any) || []) } catch (e: any) { message.error(String(e)) } }
  const openDark = () => { setDarkEdit(null); loadDarkRules(); setDarkOpen(true) }
  const doExportOptions = async () => { if (!sid) return; try { const path = await App.ProposalExportDocxWithOptions(sid, includeCover, includeTOC, darkRuleID); setExpOpen(false); message.success('已导出：' + path) } catch (e: any) { message.error(String(e)) } }
  const exportSection = async () => { if (!sid || !secSel) return; try { const path = await App.ProposalExportSectionDocx(sid, secSel); message.success('已导出单章：' + path) } catch (e: any) { message.error(String(e)) } }
  const saveDarkRule = async () => { if (!darkEdit?.name) return; try { await App.ProposalDarkRuleSave(darkEdit); setDarkEdit(null); loadDarkRules() } catch (e: any) { message.error(String(e)) } }
  const deleteDarkRule = async (id: string) => { try { await App.ProposalDarkRuleDelete(id); loadDarkRules() } catch (e: any) { message.error(String(e)) } }
  const secOptions = (sp ? flatS(sp.sections) : []).map(x => ({ value: x.id, label: x.title }))
  return <div style={{ padding: 16, height: '100%', overflow: 'auto' }}><Title level={4}>汇总导出</Title>{!sid ? <Empty description="请先选择方案" /> : <><Space style={{ marginBottom: 16 }}><Button type="primary" icon={<ExportOutlined />} onClick={hed}>导出 Word</Button><Button icon={<ExportOutlined />} onClick={he}>导出 MD</Button><Button icon={<CheckCircleOutlined />} onClick={hcov} disabled={!sp?.bidSummary?.techScoring?.length} loading={covg}>覆盖检查</Button><Button icon={<CheckCircleOutlined />} onClick={hcomp} loading={compg}>规范检查</Button><Button icon={<BookOutlined />} onClick={harchive} loading={archiving}>归档到记忆中枢</Button><Button type="primary" icon={<CheckCircleOutlined />} onClick={hchk} loading={chkg}>全面检查</Button><Button icon={<ExportOutlined />} onClick={() => { loadDarkRules(); setExpOpen(true) }}>导出设置</Button><Select value={secSel} onChange={setSecSel} style={{ width: 180 }} placeholder="选择单章导出" options={secOptions} /><Button icon={<ExportOutlined />} onClick={exportSection} disabled={!secSel}>导出单章</Button><Button icon={<BookOutlined />} onClick={openDark}>暗标规则</Button></Space><Modal title="导出设置" open={expOpen} onOk={doExportOptions} onCancel={() => setExpOpen(false)} okText="导出 Word" width={480}><Space direction="vertical" style={{ width: '100%' }}><div>封面：<Switch checked={includeCover} onChange={setIncludeCover} /></div><div>目录：<Switch checked={includeTOC} onChange={setIncludeTOC} /></div><div>暗标规则：<Select value={darkRuleID} onChange={setDarkRuleID} style={{ width: 260 }} allowClear placeholder="不选用" options={darkRules.map(r => ({ value: r.id, label: r.name }))} /></div></Space></Modal><Modal title="暗标规则库" open={darkOpen} onCancel={() => setDarkOpen(false)} footer={null} width={640}>{darkEdit && <Card size="small" style={{ marginBottom: 12 }} title="编辑规则" extra={<Space><Button size="small" type="primary" onClick={saveDarkRule}>??</Button><Button size="small" onClick={() => setDarkEdit(null)}>??</Button></Space>}><Space direction="vertical" style={{ width: '100%' }}><Input value={darkEdit.name || ''} placeholder="规则名称" onChange={e => setDarkEdit({ ...darkEdit, name: e.target.value })} /><Input value={darkEdit.description || ''} placeholder="描述" onChange={e => setDarkEdit({ ...darkEdit, description: e.target.value })} /><Space wrap>{['noBold', 'noItalic', 'noUnderline', 'noColor', 'noEmoji', 'noSpecial', 'noEmptyLines'].map(k => (<label key={k} style={{ fontSize: 12 }}><Checkbox checked={!!(darkEdit.options || {})[k]} onChange={e => setDarkEdit({ ...darkEdit, options: { ...(darkEdit.options || {}), [k]: e.target.checked } })} />{k}</label>))}</Space><label style={{ fontSize: 12 }}><Checkbox checked={!!darkEdit.enabled} onChange={e => setDarkEdit({ ...darkEdit, enabled: e.target.checked })} />启用</label></Space></Card>}{darkRules.map((r, i) => (<div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}><div><Text strong style={{ fontSize: 13 }}>{r.name}</Text><div style={{ fontSize: 12 }}>{r.description}</div></div><Space><Button size="small" onClick={() => setDarkEdit({ ...r, options: { ...(r.options || {}) } })}>编辑</Button><Button size="small" danger onClick={() => deleteDarkRule(r.id)}>删除</Button></Space></div>))}<Button type="dashed" block style={{ marginTop: 12 }} icon={<PlusOutlined />} onClick={() => setDarkEdit({ name: '', description: '', options: {}, enabled: true })}>新建规则</Button></Modal>{chk.length > 0 && <Card size="small" title="校验报告" style={{ marginBottom: 12 }}>{chk.map((it, i) => (<div key={i} style={{ display: 'flex', gap: 8, alignItems: 'flex-start', padding: '6px 0', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}><Tag color={it.status === 'pass' ? 'green' : it.status === 'fail' ? 'red' : it.status === 'warn' ? 'orange' : it.status === 'error' ? 'red' : 'default'} style={{ width: 54, textAlign: 'center', margin: 0 }}>{it.status === 'pass' ? '通过' : it.status === 'fail' ? '不通过' : it.status === 'warn' ? '提醒' : it.status === 'error' ? '异常' : '跳过'}</Tag><div style={{ flex: 1, minWidth: 0 }}><Text strong style={{ fontSize: 12 }}>{it.rule}</Text><div style={{ fontSize: 12 }}>{it.message}</div>{it.evidence ? <Text type="secondary" style={{ fontSize: 11 }}>{it.evidence}</Text> : null}{it.suggestion ? <div style={{ fontSize: 12, color: '#1677ff', marginTop: 2 }}>整改建议：{it.suggestion}</div> : null}{it.locations && it.locations.length > 0 ? <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 4 }}>{it.locations.map((loc, li) => (<span key={li} style={{ display: 'inline-flex', alignItems: 'center', gap: 4, background: 'var(--md-sys-color-surface-variant)', borderRadius: 6, padding: '1px 6px', fontSize: 11, color: 'var(--md-sys-color-on-surface-variant)' }}>{loc.excerpt ? <span style={{ fontStyle: 'italic' }}>{loc.excerpt}</span> : null}{loc.sectionId ? <Button type="link" size="small" style={{ padding: 0, fontSize: 11 }} onClick={() => onGoto(loc.sectionId)}>定位</Button> : null}</span>))}</div> : null}</div></div>))}</Card>}<Card size="small" style={{ ...cst, marginTop: 12 }} title={<Text strong>{sp?.title}</Text>}><div className="md-content" style={{ fontSize: 13, lineHeight: 1.8 }}>{sp?.sections?.map((sec, i) => <div key={sec.id} style={{ marginBottom: 12 }}><Title level={4} style={{ margin: '12px 0 4px' }}>{i + 1}. {sec.title}</Title>{sec.content ? <div dangerouslySetInnerHTML={{ __html: rm(sec.content) }} /> : <Text type="secondary">（待撰写）</Text>}{sec.children?.map(sub => <div key={sub.id} style={{ marginLeft: 16, marginBottom: 8 }}><Title level={5} style={{ margin: '8px 0 4px' }}>{sub.title}</Title>{sub.content ? <div dangerouslySetInnerHTML={{ __html: rm(sub.content) }} /> : <Text type="secondary">（待撰写）</Text>}</div>)}</div>)}</div></Card></>}</div>
}

const OfficePage: React.FC = () => {
  const [pp, setPp] = useState<P[]>([]); const [prs, setPrs] = useState<PR[]>([]); const [sid, setSid] = useState<string | null>(null); const [ssid, setSsid] = useState<string | null>(null)
  const [tt, setTt] = useState<T[]>([]); const [co, setCo] = useState(false); const [l, setL] = useState(false)
  const [nt, setNt] = useState(''); const [ntpl, setNtpl] = useState('soil-remediation-bid'); const [nr, setNr] = useState(''); const [ncat, setNcat] = useState('环保工程')
  const [nproj, setNproj] = useState(''); const [npname, setNpname] = useState('')
  const [factsOpen, setFactsOpen] = useState(false); const [factsRows, setFactsRows] = useState<{ k: string; v: string }[]>([])
  const [assetsOpen, setAssetsOpen] = useState(false); const [assets, setAssets] = useState<any[]>([]); const [assetTitle, setAssetTitle] = useState(''); const [assetTags, setAssetTags] = useState(''); const [assetBody, setAssetBody] = useState('')
  const [pipeMsg, setPipeMsg] = useState('')
  const [projSel, setProjSel] = useState(''); const [aiCtxOpen, setAiCtxOpen] = useState(false); const [reviewList, setReviewList] = useState<any[]>([])
  const [am, setAm] = useState<{ parentId: string } | null>(null); const [at, setAt] = useState(''); const [rn, setRn] = useState<{ id: string; title: string } | null>(null)
  const [tab, setTab] = useState('parse'); const sp = pp.find(x => x.id === sid)
  const rf = useCallback(async () => { try { setPp((await App.ProposalList() as any) || []) } catch (e) { } }, [])
  const rfp = useCallback(async () => { try { setPrs((await App.ProposalProjectList() as any) || []) } catch (e) { } }, [])
  const openFacts = async (projectID?: string) => { if (!projectID) return; try { const f = (await App.ProposalProjectFactsGet(projectID) as any) || {}; setFactsRows(Object.entries(f).map(([k, v]) => ({ k, v: v as string }))); setFactsOpen(true) } catch (e: any) { message.error(String(e)) } }
  const saveFacts = async () => { if (!sp?.projectId) return; try { const obj: Record<string, string> = {}; factsRows.forEach(r => { if (r.k.trim()) obj[r.k.trim()] = r.v }); await App.ProposalProjectFactsSet(sp.projectId, obj); message.success('已保存'); setFactsOpen(false) } catch (e: any) { message.error(String(e)) } }
  const loadAssets = async () => { try { setAssets((await App.ProposalAssetsList() as any) || []) } catch (e: any) { message.error(String(e)) } }
  const openAssets = () => { setAssetsOpen(true); loadAssets() }
  const addAsset = async () => { if (!assetTitle.trim() || !assetBody.trim()) return; try { await App.ProposalAssetAdd(assetTitle.trim(), assetTags.split(',').map(s => s.trim()).filter(Boolean), assetBody.trim()); setAssetTitle(''); setAssetTags(''); setAssetBody(''); loadAssets() } catch (e: any) { message.error(String(e)) } }
  const removeAsset = async (name: string) => { try { await App.ProposalAssetRemove(name); loadAssets() } catch (e: any) { message.error(String(e)) } }
  useEffect(() => { rf(); rfp(); (async () => { try { setTt((await App.ProposalTemplates() as any) || []) } catch (e) { } })() }, [rf, rfp])
  useEffect(() => { const u = EventsOn('proposal-pipeline-progress', (d: any) => { setPipeMsg((d.step || '') + ' ' + (d.status || '') + (d.detail ? ' — ' + d.detail : '')); if (d.step === 'done') { setPipeMsg(''); rf() } else if (d.step === 'error') { setPipeMsg(''); message.error(d.detail || '流水线失败') } }); return () => { if (typeof u === 'function') u() } }, [rf])
  useEffect(() => { setReviewList(sp?.reviewChecklist || []) }, [sp?.reviewChecklist])
  const os = (id: string) => { setSid(id); setTab('parse') }; const oss = (id: string) => setSsid(id)
  const on = () => setCo(true); const od = (id: string) => { Modal.confirm({ title: '确认删除？', okText: '删除', okType: 'danger', cancelText: '取消', onOk: async () => { await App.ProposalDelete(id); if (sid === id) setSid(null); rf() } }) }
  const hc = async () => { if (!nr.trim()) return; setL(true); try { let pid = nproj; if (pid === '__new__') { const np = await App.ProposalProjectCreate(npname.trim() || '未归档项目', ncat, '') as any; pid = np.id } const r = await App.ProposalCreate(nt || '未命名方案', ntpl, nr, ncat, pid) as any; setCo(false); setNt(''); setNr(''); setNproj(''); setNpname(''); await rf(); await rfp(); setSid(r.id); setTab('parse') } catch (e: any) { message.error(String(e)) }; setL(false) }
  const hadd = async () => { if (!am || !at.trim()) return; try { await App.ProposalAddSection(sid!, am.parentId, at.trim()); setAm(null); setAt(''); rf() } catch (e: any) { message.error(String(e)) } }
  const ren = (id: string) => { const s = flatS(sp?.sections || []).find(x => x.id === id); setRn({ id, title: s?.title || '' }) }
  const hren = async () => { if (!rn || !rn.title.trim()) return; try { await App.ProposalRenameSection(sid!, rn.id, rn.title.trim()); setRn(null); rf() } catch (e: any) { message.error(String(e)) } }
  const hdel = (id: string) => { Modal.confirm({ title: '删除该章节？', content: '其全部子章节内容也将一并删除。', okText: '删除', okType: 'danger', cancelText: '取消', onOk: async () => { try { await App.ProposalRemoveSection(sid!, id); if (ssid === id) setSsid(null); rf() } catch (e: any) { message.error(String(e)) } } }) }
  const addParentTitle = am ? (flatS(sp?.sections || []).find(x => x.id === am.parentId)?.title || '（顶级章节）') : ''
  const sprops = { sid, sp, ssid, onSS: oss, onR: rf, onAdd: (id: string) => setAm({ parentId: id }), onRename: ren, onDel: hdel }
  const items = [{ key: 'parse', label: <span><UploadOutlined /> 招标解析</span>, children: <ParseTab sid={sid} sp={sp} onR={rf} /> },{ key: 'outline', label: <span><UnorderedListOutlined /> 大纲生成</span>, children: <OutlineTab {...sprops} /> },{ key: 'write', label: <span><EditOutlined /> 文本编制</span>, children: <WriteTab {...sprops} /> },{ key: 'chart', label: <span><PieChartOutlined /> 图表制作</span>, children: <ChartTab {...sprops} /> },{ key: 'export', label: <span><ExportOutlined /> 汇总导出</span>, children: <ExportTab {...sprops} onGoto={(id) => { oss(id); setTab('write') }} /> }]
  const stageIdx = (st?: string) => st === 'parse' ? 0 : st === 'generate' ? 1 : st === 'check' ? 2 : st === 'format' ? 3 : 0
  const saveReview = async () => { if (!sp) return; try { await App.ProposalUpdate({ ...sp, reviewChecklist: reviewList } as any); rf(); message.success('已保存复核') } catch (e: any) { message.error(String(e)) } }
  const nextStep = () => { const st = sp?.stage; if (!st || st === 'parse') { message.info('请先完成招标解析（或点击一键流水线）'); setTab('parse') } else if (st === 'generate') { message.info('请完成文本编制（可批量生成）'); setTab('write') } else { setTab('export') } }
  return <div style={{ position: "relative", height: "100%", display: "flex" }}><aside style={{ width: 250, flexShrink: 0, borderRight: '1px solid var(--md-sys-color-outline-variant)', overflow: 'auto', padding: 12 }}><Space style={{ width: '100%', justifyContent: 'space-between' }}><Text strong style={{ fontSize: 14 }}>项目与方案</Text><Button size="small" type="primary" icon={<PlusOutlined />} onClick={on}>新建</Button></Space>{prs.map(pr => (<div key={pr.id} style={{ marginTop: 8 }}><div style={{ fontSize: 12, fontWeight: 600, color: 'var(--md-sys-color-primary)', cursor: 'pointer', padding: '2px 0' }} onClick={() => setProjSel(pr.id === projSel ? '' : pr.id)}>{pr.name}</div>{pp.filter(x => x.projectId === pr.id).map(x => (<div key={x.id} onClick={() => { setSid(x.id); setTab('parse') }} style={{ padding: '6px 8px', borderRadius: 8, marginTop: 4, cursor: 'pointer', background: sid === x.id ? 'var(--md-sys-color-primary-container)' : 'transparent', fontSize: 12 }}><div style={{ fontWeight: 500 }}>{x.title}</div><Space size={4} wrap><Text type="secondary" style={{ fontSize: 10 }}>{x.template}</Text>{(x.checkSummary?.failed || 0) > 0 && <Tag color="red" style={{ fontSize: 9, margin: 0 }}>{x.checkSummary?.failed || 0} 项不通过</Tag>}{(!x.checkSummary || (x.checkSummary.failed || 0) === 0) && (x.checkSummary?.warnings || 0) > 0 && <Tag color="orange" style={{ fontSize: 9, margin: 0 }}>{x.checkSummary?.warnings || 0} 提醒</Tag>}</Space></div>))}</div>))}</aside><div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', position: 'relative' }}><div style={{ padding: '8px 16px 0' }}><Steps size="small" current={stageIdx(sp?.stage)} items={[{ title: '招标解析' }, { title: '大纲生成' }, { title: '文本编制' }, { title: '全面检查' }, { title: '排版导出' }]} /><Space style={{ marginTop: 8 }}><Button size="small" type="primary" icon={<RobotOutlined />} onClick={() => { setPipeMsg('流水线运行中...'); App.ProposalRunPipeline(sid!) }} disabled={!sid}>一键流水线</Button><Button size="small" onClick={nextStep} disabled={!sid}>下一步</Button><Button size="small" icon={<RobotOutlined />} onClick={() => setAiCtxOpen(true)}>AI 上下文</Button>{pipeMsg && <Spin size="small" />}{pipeMsg && <Text type="secondary" style={{ fontSize: 12 }}>{pipeMsg}</Text>}</Space></div><Tabs activeKey={tab} onChange={setTab} items={items} destroyInactiveTabPane={false} style={{ height: '100%' }} tabBarStyle={{ padding: '0 16px', marginBottom: 0 }} /><Modal title="新建方案" open={co} onOk={hc} onCancel={() => setCo(false)} confirmLoading={l} okText="创建" width={560}><Space direction="vertical" style={{ width: '100%' }} size={12}><div><Text strong>分类</Text><Select value={ncat} onChange={setNcat} style={{ width: '100%', marginTop: 4 }} options={cats.filter(c => c !== '全部').map(c => ({ value: c, label: c }))} /></div><div><Text strong>模板</Text><Select value={ntpl} onChange={setNtpl} style={{ width: '100%', marginTop: 4 }} options={tt.map(x => ({ value: x.id, label: x.name }))} /></div><div><Text strong>项目</Text><Select value={nproj} onChange={setNproj} style={{ width: '100%', marginTop: 4 }} options={[...prs.map(x => ({ value: x.id, label: x.name })), { value: '__new__', label: '＋ 新建项目' }]} />{nproj === '__new__' && <Input value={npname} onChange={e => setNpname(e.target.value)} placeholder="输入项目名称（留空=未归档项目）" style={{ marginTop: 8 }} />}</div><div><Text strong>标题</Text><Input value={nt} onChange={e => setNt(e.target.value)} placeholder="留空则 AI 自动生成" style={{ marginTop: 4 }} /></div><div><Text strong>需求 <Text type="danger">*</Text></Text><TextArea value={nr} onChange={e => setNr(e.target.value)} placeholder="描述方案需求..." rows={5} style={{ marginTop: 4 }} /></div></Space></Modal><Modal title="新增章节" open={!!am} onOk={hadd} onCancel={() => { setAm(null); setAt('') }} okText="添加" width={420}><div><Text strong>父章节</Text><div style={{ fontSize: 12, color: '#888', marginBottom: 8 }}>{addParentTitle}</div></div><Text strong>标题 <Text type="danger">*</Text></Text><Input value={at} onChange={e => setAt(e.target.value)} placeholder="输入章节标题" onPressEnter={hadd} style={{ marginTop: 4 }} /></Modal><Modal title="重命名章节" open={!!rn} onOk={hren} onCancel={() => setRn(null)} okText="保存" width={420}><Text strong>标题 <Text type="danger">*</Text></Text><Input value={rn?.title || ''} onChange={e => setRn({ ...rn!, title: e.target.value })} onPressEnter={hren} style={{ marginTop: 4 }} /></Modal>      {/* 绑定模型卡（左下角浮动） */}<div style={{ position: "absolute", top: 8, right: 16, zIndex: 40 }}><Button size="small" icon={<BookOutlined />} onClick={() => openFacts(sp?.projectId)} disabled={!sp?.projectId}>项目事实</Button><Button size="small" icon={<BookOutlined />} onClick={openAssets}>素材库</Button></div><div style={{ position: "absolute", left: 12, bottom: 12, zIndex: 50 }}><FeatureModelBar feature="office" label="方案" /></div><Modal title="项目事实基线" open={factsOpen} onOk={saveFacts} onCancel={() => setFactsOpen(false)} okText="保存" width={560}>{factsRows.map((r, i) => (<Space key={i} style={{ width: '100%', marginBottom: 8 }}><Input value={r.k} style={{ width: 180 }} placeholder="键" onChange={e => setFactsRows(fs => fs.map((x, j) => j === i ? { ...x, k: e.target.value } : x))} /><Input value={r.v} placeholder="值" onChange={e => setFactsRows(fs => fs.map((x, j) => j === i ? { ...x, v: e.target.value } : x))} /></Space>))}<Button type="dashed" block icon={<PlusOutlined />} onClick={() => setFactsRows(fs => [...fs, { k: '', v: '' }])}>新增</Button></Modal><Modal title="素材库（业绩/人员/设备/段落）" open={assetsOpen} onCancel={() => setAssetsOpen(false)} footer={null} width={680}><Space style={{ marginBottom: 12 }} wrap><Input placeholder="搜索素材" style={{ width: 220 }} onChange={e => { const q = e.target.value; setAssets((assets || []).filter(x => !q || (x.title || '').includes(q) || (x.body || '').includes(q))) }} /><Input value={assetTitle} placeholder="标题（如：某公司业绩）" style={{ width: 200 }} onChange={e => setAssetTitle(e.target.value)} /><Input value={assetTags} placeholder="标签，逗号分隔" style={{ width: 150 }} onChange={e => setAssetTags(e.target.value)} /><Button type="primary" size="small" onClick={addAsset}>新增</Button></Space><Input.TextArea value={assetBody} rows={2} placeholder="正文内容" onChange={e => setAssetBody(e.target.value)} /><div style={{ marginTop: 12, maxHeight: 380, overflow: 'auto' }}>{(assets || []).map((x, i) => (<Card key={i} size="small" style={{ marginBottom: 8 }} title={x.title} extra={<Button type="text" size="small" danger onClick={() => removeAsset(x.name)}>删除</Button>}>{(x.tags || []).map((t: string) => <Tag key={t} style={{ marginRight: 4 }}>{t}</Tag>)}<div style={{ fontSize: 13, whiteSpace: 'pre-wrap' }}>{x.body}</div></Card>))}</div></Modal></div><Drawer title="AI 上下文" width={360} open={aiCtxOpen} onClose={() => setAiCtxOpen(false)}><Card size="small" title="招标要点" style={{ marginBottom: 12 }}><div style={{ fontSize: 12, lineHeight: 1.9 }}><div>概况：{sp?.bidSummary?.overview || '—'}</div><div>工期：{sp?.bidSummary?.duration || '—'}</div><div>评分项：{sp?.bidSummary?.techScoring?.length || 0} 个；资质：{sp?.bidSummary?.qualification?.length || 0} 个</div><div>废标条款：{sp?.bidSummary?.redLines?.length || 0} 条</div></div></Card><Card size="small" title="检查摘要" style={{ marginBottom: 12 }}><div style={{ fontSize: 12, lineHeight: 1.9 }}><div>不通过：<span style={{ color: '#ff4d4f' }}>{sp?.checkSummary?.failed || 0}</span> 项；提醒：<span style={{ color: '#fa8c16' }}>{sp?.checkSummary?.warnings || 0}</span> 项；合计 {sp?.checkSummary?.total || 0} 项</div><Text type="secondary" style={{ fontSize: 11 }}>来源定位：在招标解析中点击来源 chip 可跳原文</Text></div></Card><Card size="small" title="复核清单（单人复核）" extra={<Button size="small" type="primary" onClick={saveReview}>保存</Button>}>{reviewList.map((r, i) => (<div key={r.id || i} style={{ padding: '4px 0' }}><label style={{ fontSize: 13, display: 'flex', alignItems: 'center', gap: 8 }}><Checkbox checked={!!r.done} onChange={e => setReviewList(ls => ls.map((x, j) => j === i ? { ...x, done: e.target.checked } : x))} />{r.label}</label></div>))}</Card></Drawer></div>
}
function rm(md: string): string { let h = md.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); h = h.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => '<pre><code class="language-' + (lang || 'plain') + '">' + code.trim() + '</code></pre>'); h = h.replace(/`([^`]+)`/g, '<code>$1</code>'); h = h.replace(/^### (.+)$/gm, '<h3>$1</h3>'); h = h.replace(/^## (.+)$/gm, '<h2>$1</h2>'); h = h.replace(/^# (.+)$/gm, '<h1>$1</h1>'); h = h.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>'); h = h.replace(/\*(.+?)\*/g, '<em>$1</em>'); h = h.replace(/^[\-\*] (.+)$/gm, '<li>$1</li>'); h = h.replace(/((?:<li>.*<\/li>\n?)+)/g, '<ul>$1</ul>'); h = h.replace(/^---+$/gm, '<hr/>'); return h.split('\n').map(l => /^</.test(l) ? l : l.trim() ? '<p>' + l + '</p>' : '<br/>').join('\n') }
export default OfficePage
